import{_ as o,l,o as e,c as n,v as t,p as s,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"地理复制","description":"","frontmatter":{"title":"地理复制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/geo-replication.md","filePath":"cs/geo-replication.md","lastUpdated":1789023840000}'),A={name:"cs/geo-replication.md"};function h(E,a,S,C,T,_){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="地理复制" tabindex="-1">地理复制 <a class="header-anchor" href="#地理复制" aria-label="Permalink to &quot;地理复制&quot;">​</a></h1><div class="epigraph"><p>跨数据中心的延迟下限是光速。同步复制买线性一致，付跨洋 RTT；异步复制买本地写，付冲突与数据丢失窗口。</p><footer>—— 据 Corbett et al., Spanner, OSDI 2012；Lloyd et al., COPS, SOSP 2011；PACELC 整理</footer></div><p>上一课<a href="/cs/distributed-id">分布式 ID</a>的时间序在跨区更不可靠。缺口是<strong>多机房同一逻辑数据</strong>：CAP 的分区变成经常性的延迟与真切断。本课钉同步/异步地理复制与因果+，不重写 TrueTime 全部。后课滚动升级是机房内变更，可与跨区流量编排叠在一起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同步：写等跨区多数派，线性一致可能，延迟 ≥ RTT。异步：本地提交，对端追，RPO &gt; 0，冲突用 LWW/CRDT/会话。COPS：在最终一致上加强因果+（读到的值的依赖都在）。Spanner：用 TrueTime 的 \\(\\varepsilon\\) 做 commit wait，给外部一致事务——依赖时钟 API，不是普通 NTP。</p><p>缺口：把「多 AZ」当地理。同城同步与跨洋异步档位不同。DNS 切流量不是 fencing。</p><p><span class="marginnote">Spanner 论文是外部一致与 TrueTime。COPS 是因果+。二者都不要缩写成「有了地理复制就强一致」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读本地、写本地：AP/L。写本地、读全局：看是否等复制。写全局主：一区当主，他区只读，failover 接<a href="/cs/primary-backup-failover">主备</a>与脑裂。多主：必须冲突规则。</p>',9)),(e(),s(c,null,{default:r(()=>[d(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%22%5D%20--%3E%20SYNC%7B%22%E7%AD%89%E8%B7%A8%E5%8C%BA%3F%22%7D%0A%20%20SYNC%20--%3E%7C%22%E6%98%AF%22%7C%20LIN%5B%22%E5%8F%AF%E7%BA%BF%E6%80%A7%20%2F%20%E5%A4%96%E9%83%A8%E4%B8%80%E8%87%B4%22%5D%0A%20%20SYNC%20--%3E%7C%22%E5%90%A6%22%7C%20ASY%5B%22%E6%9C%AC%E5%9C%B0%E6%88%90%E5%8A%9F%20%2B%20%E8%BF%BD%E8%B5%B6%22%5D%0A%20%20ASY%20--%3E%20CF%5B%22%E5%86%B2%E7%AA%81%20%2F%20%E5%9B%A0%E6%9E%9C%2B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>对象存储跨区复制通常异步，接 S3 课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分区：跨区链路比机房内更容易长时间分区。CP 系统少数派机房必须拒写。PACELC 的 EL 在无分区时仍付 RTT。时钟：跨区 \\(\\varepsilon\\) 更大，HLC 更常靠计数；TrueTime 用 GPS/原子钟把 \\(\\varepsilon\\) 暴露。</p><p>本课不写具体云厂商的 Active-Active 广告。也不写 LOB 跨区撮合。</p><p>会话：用户跟着 DNS 跳机房会破 RYW，除非把会话向量带走或粘滞。接会话保证课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Spanner 并发控制。后课默认：跨区先选 RPO/RTO 与一致档；不要默认多主 LWW。滚动升级下一课处理版本异构，地理复制期间双版本更常见。TLA+ 最后课给这些协议一个规格语言。</p><p>光速是墙。协议只能把墙换成冲突或延迟，不能拆墙。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同步跨区：延迟换强一致；异步：RPO 与冲突。</li><li>COPS 因果+、Spanner 外部一致是不同档。</li><li>跨区分区更长，少数派必须有拒写故事。</li><li>出处：Corbett et al., OSDI 2012；Lloyd et al., SOSP 2011。</li></ul>',10))])}const u=o(A,[["render",h]]);export{P as __pageData,u as default};
